def chain_follow(chain):
    tokens = chain.split(', ')
    first = tokens[0]
    second = tokens[1]
    result = []
    for token in tokens[2:]:
        if token == first:
            result.append(second)
        else:
            result.append(token)
    return ','.join(result)

